$cut=$legacy.IndexOf('Add-Type -TypeDefinition $code')
if($cut-lt0){throw 'Original cleanup native-boundary builder missing'}
# Reuse native boundaries, not the original90 oracle. Its independent cases still run separately.
$builder=$legacy.Substring(0,$cut).Replace('$PSScriptRoot',("'"+$PSScriptRoot.Replace("'","''")+"'"))
. ([scriptblock]::Create($builder)) -RepositoryRoot $rebindRepo
