function RebindTranslate([string]$s){
 $s=$s -creplace '\bfactionKey\b','factionValue'
 $s=Translate $s
 $s=$s.Replace('vector','Vec').Replace('System.GetTickCount()','Clock.Now').Replace('Math.AbsFloat(','Math.Abs(').Replace('float.MAX','float.MaxValue').Replace('string.Format(','Fmt.Format(')
 $s=$s.Replace('m_Assignment','Assignment').Replace('m_RetirementIdentity','Admission').Replace('m_sCausationId','Cause')
 return $s
}
function Inject([string]$Class,[string]$Text){$script:code=$script:code.Replace('public class '+$Class+':Native{','public class '+$Class+':Native{'+$Text)}
function Actual([string]$Source,[string]$Name,[string]$Signature){return $Signature+(RebindTranslate (Body $Source $Name))}
