$snapshot=$snapshot.Replace('AICF_EGroupRole','int').Replace('AICF_EGroupUnitType','int').Replace('AICF_EOrderTargetKind ','int ')
$snapshot=$snapshot.Replace('public class AICF_StrategicAssignmentSnapshot:Native{','public class AICF_StrategicAssignmentSnapshot:Native{')
$snapshot=$snapshot.Replace('public class AICF_StrategicAssignmentSnapshot:Native'+"`r`n"+'{','public class AICF_StrategicAssignmentSnapshot:Native'+"`r`n"+'{')
$brace=$snapshot.IndexOf('{')+1
$snapshot=$snapshot.Insert($brace,'public AICF_StrategicAssignmentSnapshot():this("USSR",0,"S0",1,null,1,1,"MOVE_AND_HOLD",0,null,new Vec(1,2,3),3,4,5,null,0){}public SCR_AIGroup Group{get{return m_Group;}set{m_Group=value;}}public int Assignment{get{return m_iAssignmentRevision;}set{m_iAssignmentRevision=value;}}public int Intent{get{return m_iStrategicIntentRevision;}set{m_iStrategicIntentRevision=value;}}public int Base{get{return m_iBaseRevision;}set{m_iBaseRevision=value;}}')
$code=$code.Replace($snapshotLine,$snapshot)
