$cases=@'
public static class RebindCases{
static void Need(bool x,string why){if(!x)throw new Exception(why);}
static Env Setup(){var e=new Env();e.Trip.Terminal=false;for(int i=0;i<4;i++){var c=new ChimeraCharacter{Id=4000+i,World=Env.Game.World};c.Controller.Life=ECharacterLifeState.ALIVE;Env.Game.World.Map[c.Id]=c;e.Admission.m_aMembers.Add(new AICF_TripRetirementMember{m_Character=c,m_Id=c.Id,m_sRpl=c.Rpl.Value.ToString(),m_World=c.World,m_Rpl=c.Rpl,m_Controller=c.Controller});}return e;}
static AICF_StrategicAssignmentSnapshot Next(Env e,bool newIntent){e.Trip.Slot.RecordRuntimeWaypointReplacement();if(newIntent){e.Trip.Slot.Intent++;e.Trip.Slot.Position=new Vec(20,2,30);}AICF_StrategicAssignmentSnapshot s;Need(new Planning().TryCreateAssignmentSnapshot(e.Trip.Slot,new SCR_CampaignFaction(),5,out s),"actual planner snapshot");return s;}
static AICF_CapturedDeadCleanupIdentity Terminal(Env e){Need(e.Trip.Slot.SetVehiclePreset(null,1),"actual RESET");new RebindController().EndVehicleControl(e.Trip,e.Trip.Slot,e.Job.m_Fleet,new SCR_CampaignFaction(),AICF_ETransportTripPhase.FALLBACK,"VEHICLE_PRESET_SUPERSEDED","PRESET_CHANGED",true);Need(e.Trip.IsTerminal(),"actual End + CommitTransition");e.Job.m_CapturedDeadCleanup=e.Trip.CaptureCapturedDeadCleanupIdentity(e.Job);return e.Job.m_CapturedDeadCleanup;}
static bool OldTerminal(Env e){var original=e.Admission;var old=new OldAdmission{m_CapturedGroup=e.Group,m_GroupId=e.Group.Id,m_GroupRpl=e.Group.Rpl.Value,m_AdmissionGroupRpl=e.Group.Rpl,m_AdmissionWorld=Env.Game.World,m_AdmissionAssignment=original.m_AdmissionAssignment,m_aMembers=original.m_aMembers};e.Trip.Admission=old;bool result=old.OldTerminal(e.Trip);e.Trip.Admission=original;return result;}
public static int Run(){int n=0;foreach(bool intent in new[]{false,true}){var e=Setup();var original=e.Admission.m_AdmissionAssignment;var actor=e.Admission.m_aMembers[0];var s=Next(e,intent);Need(new RebindController().CommitRetarget(e.Trip,s,"safe-reuse",e.Trip.Slot),"actual controller commit");Need(e.Admission.m_AdmissionAssignment==original&&e.Admission.m_aMembers[0]==actor&&e.Trip.m_CleanupAssignmentRebind==null,"immutable admission/actors + token consumed");Need(Terminal(e)!=null,"accepted commit carries cleanup fence");Need(!OldTerminal(e),"actual original r31 admission rejects committed replacement");Need(e.Manager.Run(e.Job,e.Vehicle,10000)&&e.Actor.Access.Kicks==1,"linked actual physical handler gets original DEAD actor");Need(e.Admission.m_aMembers.Count()==5,"original five retained");for(int i=1;i<5;i++)Need(e.Admission.m_aMembers[i].m_Controller.GetLifeState()==ECharacterLifeState.ALIVE,"four original survivors alive");n+=7;}
foreach(string k in new[]{"noCommit","forgedNoCommit","foreignCurrent","wrongCandidate","oldChanged","leaseSwap","leaseGen","vehicleGen","lifecycle","terminal","slotGen","slotRevision","slotIntent","slotTarget","group","owner","ownerNull","world","nativeLease","nativeCurrent","nativeSuccessor","nativeTerminal","nativeToken","nativeFinalWorld","nativeFinalAuthority","cancelThenComplete"}){var e=Setup();var s=Next(e,false);var token=e.Trip.BeginCleanupAssignmentRebind(s,e.Trip.Slot);Need(token!=null,"token setup "+k);if(k!="noCommit"&&k!="forgedNoCommit"){if(k=="oldChanged")e.Trip.Assignment=new AICF_StrategicAssignmentSnapshot{Group=e.Group};var candidate=k=="wrongCandidate"?new AICF_StrategicAssignmentSnapshot{Group=e.Group,Assignment=s.Assignment}:s;Need(e.Trip.CommitRetarget(candidate,"accepted"),"actual commit still accepted "+k);}switch(k){case"forgedNoCommit":e.Trip.Assignment=s;break;case"foreignCurrent":e.Trip.Assignment=new AICF_StrategicAssignmentSnapshot{Group=e.Group,Assignment=s.Assignment};break;case"leaseSwap":e.Trip.Lease=new AICF_VehicleLease{Vehicle=e.Vehicle};break;case"leaseGen":e.Trip.Lease.LeaseGen++;break;case"vehicleGen":e.Trip.Lease.VehicleGen++;break;case"lifecycle":e.Trip.Lease.Lifecycle="successor";break;case"terminal":e.Trip.Terminal=true;break;case"slotGen":e.Trip.Slot.Generation++;break;case"slotRevision":e.Trip.Slot.Revision++;break;case"slotIntent":e.Trip.Slot.Intent++;break;case"slotTarget":e.Trip.Slot.Position=new Vec(9,9,9);break;case"group":e.Trip.Slot.Group=new SCR_AIGroup();break;case"owner":e.Trip.Admission=new AICF_TripRetirementIdentity();break;case"ownerNull":e.Trip.Admission=null;break;case"world":Env.Game.World=new BaseWorld();break;case"nativeLease":e.Group.Rpl.Read=()=>e.Trip.Lease=new AICF_VehicleLease();break;case"nativeCurrent":e.Group.Rpl.Read=()=>e.Trip.Assignment=new AICF_StrategicAssignmentSnapshot{Group=e.Group,Assignment=s.Assignment};break;case"nativeSuccessor":e.Group.Rpl.Read=()=>{e.Trip.Slot.Revision++;var successor=new AICF_StrategicAssignmentSnapshot{Group=e.Group,Assignment=e.Trip.Slot.Revision};e.Trip.BeginCleanupAssignmentRebind(successor,e.Trip.Slot);};break;case"nativeTerminal":e.Group.Rpl.Read=()=>e.Trip.Terminal=true;break;case"nativeToken":e.Group.Rpl.Read=()=>e.Trip.InvalidateCleanupAssignmentRebind();break;case"nativeFinalWorld":e.Group.ComponentReadAt=e.Group.ComponentReads+2;e.Group.ComponentRead=()=>Env.Game.World=new BaseWorld();break;case"nativeFinalAuthority":e.Group.ComponentReadAt=e.Group.ComponentReads+2;e.Group.ComponentRead=()=>Replication.Server=false;break;case"cancelThenComplete":e.Trip.CancelCleanupAssignmentRebind(token);break;}Need(!e.Trip.CompleteCleanupAssignmentRebind(token,e.Trip.Slot),"unsafe transfer rejected "+k);Need(e.Admission.m_CleanupAssignment==e.Admission.m_AdmissionAssignment,"no unsafe adoption "+k);n++;}
{var e=Setup();var s=Next(e,false);var outer=e.Trip.BeginCleanupAssignmentRebind(s,e.Trip.Slot);var successor=e.Trip.BeginCleanupAssignmentRebind(s,e.Trip.Slot);e.Trip.CancelCleanupAssignmentRebind(outer);Need(e.Trip.OwnsCleanupAssignmentRebind(successor),"stale cancel retains successor");Need(e.Trip.CommitRetarget(s,"nested")&&e.Trip.CompleteCleanupAssignmentRebind(successor,e.Trip.Slot),"successor accepted exact token");Need(!e.Trip.CompleteCleanupAssignmentRebind(outer,e.Trip.Slot),"outer cannot transfer twice");n+=3;}
{var e=Setup();var s=Next(e,false);Need(new RebindController().CommitRetarget(e.Trip,s,"safe-reuse",e.Trip.Slot),"commit before capability");var cap=Terminal(e);Need(cap!=null,"terminal capability");e.Trip.Assignment=new AICF_StrategicAssignmentSnapshot{Group=e.Group,Assignment=s.Assignment,Intent=s.Intent,Base=s.Base};Need(!cap.IsCurrent(e.Job,e.Vehicle),"same-fields foreign post-capture snapshot remains rejected");n++;}
{var e=Setup();var s=Next(e,false);var token=e.Trip.BeginCleanupAssignmentRebind(s,e.Trip.Slot);e.Trip.StopCleanupAssignmentRebind();Need(!e.Trip.OwnsCleanupAssignmentRebind(token)&&e.Trip.BeginCleanupAssignmentRebind(s,e.Trip.Slot)==null,"Stop invalidates pending and prevents reentrant bookkeeping restart");Need(e.Trip.CommitRetarget(s,"accepted-after-stop"),"Stop bookkeeping does not change gameplay retarget result");n+=2;}{var e=Setup();var s=Next(e,false);var token=e.Trip.BeginCleanupAssignmentRebind(s,e.Trip.Slot);token.m_Trip=null;token.RecordCommitted(null,s);Need(!token.m_bCommitted,"expired weak Trip/null caller does not dereference or accept");token.RecordCommitted(e.Trip,null);Need(!token.m_bCommitted,"null accepted candidate cannot record commit");n+=2;}return n;}}
'@
